22	// TODO: Also generalize this routine and handle dynamic loading properly.
23	void init_tls(TLSDescriptor &tls_descriptor) {
24	  if (app.tls.size == 0) {
25	    tls_descriptor.size = 0;
26	    tls_descriptor.tp = 0;
27	    return;
28	  }
29	
30	  // We will assume the alignment is always a power of two.
31	  uintptr_t tls_size = app.tls.size & -app.tls.align;
32	  if (tls_size != app.tls.size)
33	    tls_size += app.tls.align;
34	
35	  // Per the x86_64 TLS ABI, the entry pointed to by the thread pointer is the
36	  // address of the TLS block. So, we add more size to accomodate this address
37	  // entry.
38	  // We also need to include space for the stack canary. The canary is at
39	  // offset 0x28 (40) and is of size uintptr_t.
40	  uintptr_t tls_size_with_addr = tls_size + sizeof(uintptr_t) + 40;
41	
42	  ErrorOr<void *> mmap_ret =
43	      linux_syscalls::mmap(nullptr, tls_size_with_addr, PROT_READ | PROT_WRITE,
44	                           MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
45	  if (!mmap_ret.has_value())
46	    syscall_impl<long>(SYS_exit, 1);
47	  uintptr_t *tls_addr = static_cast<uintptr_t *>(mmap_ret.value());
48	
49	  // x86_64 TLS faces down from the thread pointer with the first entry
50	  // pointing to the address of the first real TLS byte.
51	  uintptr_t end_ptr = reinterpret_cast<uintptr_t>(tls_addr) + tls_size;
52	  *reinterpret_cast<uintptr_t *>(end_ptr) = end_ptr;
53	
54	  inline_memcpy(reinterpret_cast<char *>(tls_addr),
55	                reinterpret_cast<const char *>(app.tls.address),
56	                app.tls.init_size);
57	  uintptr_t *stack_guard_addr = reinterpret_cast<uintptr_t *>(end_ptr + 40);
58	  // Setting the stack guard to a random value.
59	  // We cannot call the get_random function here as the function sets errno on
60	  // failure. Since errno is implemented via a thread local variable, we cannot
61	  // use errno before TLS is setup. The linux_syscalls wrapper is safe as it
62	  // reports errors via ErrorOr instead of errno.
63	  ErrorOr<ssize_t> stack_guard_retval =
64	      linux_syscalls::getrandom(stack_guard_addr, sizeof(uint64_t), 0);
65	  if (!stack_guard_retval.has_value())
66	    syscall_impl(SYS_exit, 1);
67	
68	  tls_descriptor = {tls_size_with_addr, reinterpret_cast<uintptr_t>(tls_addr),
69	                    end_ptr};
70	  return;
71	}
72	
73	void cleanup_tls(uintptr_t addr, uintptr_t size) {
74	  if (size == 0)
75	    return;
76	  linux_syscalls::munmap(reinterpret_cast<void *>(addr), size);
77	}
78	
79	// Sets the thread pointer to |val|. Returns true on success, false on failure.
80	bool set_thread_ptr(uintptr_t val) {
81	  return syscall_impl(SYS_arch_prctl, ARCH_SET_FS, val) != -1;
82	}
83	} // namespace LIBC_NAMESPACE_DECL
